-- ⚠️ 2026-10-15 (demande front « modeles-guide-cao », §B5 ; décision du pilote n° 16) — la commission refuse de valider : avant la
-- dernière signature, le président (ou son représentant désigné pour le rapport) retire le rapport d'évaluation avec un motif. Le
-- rapport retiré est gardé ici (PDF, Word, signatures déjà posées), consultable et marqué « retiré » ; le rapport suivant le cite.
CREATE TABLE IF NOT EXISTS public.t_evaluation_rapport_retire (
    "ID"           bigint GENERATED BY DEFAULT AS IDENTITY,
    "ID_DMC"       bigint NOT NULL,
    "PRODUIT_LE"   timestamp without time zone NOT NULL,
    "PRODUIT_PAR"  character varying(100),
    "RETIRE_LE"    timestamp without time zone NOT NULL,
    "RETIRE_PAR"   character varying(20) NOT NULL,
    "MOTIF"        text NOT NULL,
    "SIGNATURES"   text,
    "PDF"          bytea,
    "DOCX"         bytea,
    CONSTRAINT t_evaluation_rapport_retire_pkey PRIMARY KEY ("ID"),
    CONSTRAINT fk_evaluation_rapport_retire_evaluation FOREIGN KEY ("ID_DMC") REFERENCES public.t_evaluation ("ID_DMC") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_evaluation_rapport_retire_dmc ON public.t_evaluation_rapport_retire ("ID_DMC");
